// Input: {entry_id: string}. Credential-free public reads on authorised RCSB/Crossref origins only.
const id = String(input.entry_id || '').trim().toUpperCase();
if (!id) throw Error('entry_id required');
async function json(url) { const r = await fetch(url); if (!r.ok) throw Error(`HTTP ${r.status}`); return r.json(); }
const query = 'query($id:String!){entry(entry_id:$id){rcsb_id rcsb_primary_citation{id title pdbx_database_id_DOI journal_abbrev year}}}';
const r = await json('https://data.rcsb.org/graphql?' + new URLSearchParams({query, variables:JSON.stringify({id})}));
if (r.errors) throw Error(JSON.stringify(r.errors));
const entry = r.data?.entry;
const c = entry?.rcsb_primary_citation;
if (!entry || c?.id !== 'primary' || !c.pdbx_database_id_DOI) throw Error('Primary citation DOI unavailable');
// Discover the public bibliographic interface before using it.
const spec = await json('https://api.crossref.org/swagger-docs');
if (!spec.paths?.['/works/{doi}']) throw Error('Crossref works interface unavailable');
const record = await json('https://api.crossref.org/works/' + encodeURIComponent(c.pdbx_database_id_DOI));
const m = record.message;
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
if (record.status !== 'ok' || m?.DOI?.toLowerCase() !== c.pdbx_database_id_DOI.toLowerCase()) throw Error('DOI verification failed');
if (m.type !== 'journal-article') throw Error('Primary citation is not verified as a journal research publication');
if (!Array.isArray(m.title) || !m.title.length || !m.title.some(t => norm(t) === norm(c.title))) throw Error('Primary citation title mismatch');
if (!m.publisher || !m['container-title']?.length) throw Error('Publication metadata incomplete');
return {entry_id:entry.rcsb_id, doi:m.DOI, title:m.title, publisher:m.publisher};

